From 39f6162652a46ef6a222a6c796991fb987c74a79 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:21:49 +0100
Subject: [PATCH] lockscreen, sddm-theme: show Num Lock state after a failed
 login

A rejected password gave no hint that Num Lock was on, which is easy to
miss on laptops where it turns letters into digits. Show it after a
failed attempt, not before, as many keyboards keep it on all the time.

BUG: 391168
---
 desktoppackage/contents/lockscreen/LockScreenUi.qml | 11 +++++++++++
 sddm-theme/Main.qml                                 | 11 +++++++++++
 2 files changed, 22 insertions(+)

diff --git a/desktoppackage/contents/lockscreen/LockScreenUi.qml b/desktoppackage/contents/lockscreen/LockScreenUi.qml
index 065a33c131..deb88346f8 100644
--- a/desktoppackage/contents/lockscreen/LockScreenUi.qml
+++ b/desktoppackage/contents/lockscreen/LockScreenUi.qml
@@ -36,6 +36,8 @@ Item {
     property bool expectingPrompt: false // this is set for real when an authenticator is selected
     // <!* Whether we are expected to visualize the prompt message for the authenticator *>
     property bool showPrompt: false // this is set for real when an authenticator is selected
+    // Num Lock is only worth mentioning once a password was rejected, as it is on all the time with many keyboards
+    property bool unlockFailed: false

     function handleMessage(msg) {
         if (!msg) {
@@ -64,6 +66,7 @@ Item {
             }
             const msg = i18ndc("plasma_shell_org.kde.plasma.desktop", "@info:status", "Unlocking failed");
             lockScreenUi.handleMessage(msg);
+            lockScreenUi.unlockFailed = true;
             root.clearPassword();
             authenticator.startAuthenticating();
             notificationRemoveTimer.restart();
@@ -123,6 +126,11 @@ Item {
         key: Qt.Key_CapsLock
     }

+    KeyboardIndicator.KeyState {
+        id: numLockState
+        key: Qt.Key_NumLock
+    }
+
     Connections {
         target: sessionManagement
         function onAboutToSuspend() {
@@ -387,6 +395,9 @@ Item {
                     if (capsLockState.locked) {
                         parts.push(i18ndc("plasma_shell_org.kde.plasma.desktop", "@info:status", "Caps Lock is on"));
                     }
+                    if (numLockState.locked && lockScreenUi.unlockFailed) {
+                        parts.push(i18ndc("plasma_shell_org.kde.plasma.desktop", "@info:status", "Num Lock is on"));
+                    }
                     if (accessibilityStatus.slowKeysEnabled) {
                         parts.push(i18ndc("plasma_shell_org.kde.plasma.desktop", "@info:status", "Slow Keys are enabled"));
                     }
diff --git a/sddm-theme/Main.qml b/sddm-theme/Main.qml
index 3379ead93e..121e53bd84 100644
--- a/sddm-theme/Main.qml
+++ b/sddm-theme/Main.qml
@@ -30,6 +30,8 @@ Item {
     height: 900

     property string notificationMessage
+    // Num Lock is only worth mentioning once a password was rejected, as it is on all the time with many keyboards
+    property bool loginFailed: false

     LayoutMirroring.enabled: Application.layoutDirection === Qt.RightToLeft
     LayoutMirroring.childrenInherit: true
@@ -39,6 +41,11 @@ Item {
         key: Qt.Key_CapsLock
     }

+    KeyboardIndicator.KeyState {
+        id: numLockState
+        key: Qt.Key_NumLock
+    }
+
     Item {
         id: wallpaper
         anchors.fill: parent
@@ -200,6 +207,9 @@ Item {
                     if (capsLockState.locked) {
                         parts.push(i18ndc("plasma-desktop-sddm-theme", "@info:status",  "Caps Lock is on"));
                     }
+                    if (numLockState.locked && root.loginFailed) {
+                        parts.push(i18ndc("plasma-desktop-sddm-theme", "@info:status", "Num Lock is on"));
+                    }
                     if (root.notificationMessage) {
                         parts.push(root.notificationMessage);
                     }
@@ -510,6 +520,7 @@ Item {
         target: sddm
         function onLoginFailed() {
             notificationMessage = i18ndc("plasma-desktop-sddm-theme", "@info:status", "Login Failed")
+            loginFailed = true
             footer.enabled = true
             mainStack.enabled = true
             userListComponent.userList.opacity = 1
-- 
2.53.0

From d22a800b3490ec2933b0b0fc207830be548f8b24 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:21:49 +0100
Subject: [PATCH] greeter: show Num Lock state after a failed login

A rejected password gave no hint that Num Lock was on, which is easy to
miss on laptops where it turns letters into digits. Show it after a
failed attempt, not before, as many keyboards keep it on all the time.

BUG: 391168
---
 src/frontend/greeter/qml/Main.qml | 14 ++++++++++++++
 1 file changed, 14 insertions(+)

diff --git a/src/frontend/greeter/qml/Main.qml b/src/frontend/greeter/qml/Main.qml
index f8e97403..0579019f 100644
--- a/src/frontend/greeter/qml/Main.qml
+++ b/src/frontend/greeter/qml/Main.qml
@@ -31,6 +31,8 @@ Item {
     Kirigami.Theme.inherit: false

     property string notificationMessage
+    // Num Lock is only worth mentioning once a password was rejected, as it is on all the time with many keyboards
+    property bool loginFailed: false

     LayoutMirroring.enabled: Qt.application.layoutDirection === Qt.RightToLeft
     LayoutMirroring.childrenInherit: true
@@ -40,6 +42,11 @@ Item {
         key: Qt.Key_CapsLock
     }

+    KeyboardIndicator.KeyState {
+        id: numLockState
+        key: Qt.Key_NumLock
+    }
+
     BreezeComponents.RejectPasswordAnimation {
         id: rejectPasswordAnimation
         target: mainStack
@@ -175,6 +182,9 @@ Item {
                     if (capsLockState.locked) {
                         parts.push(KI18n.i18nd("plasma_login", "Caps Lock is on"));
                     }
+                    if (numLockState.locked && root.loginFailed) {
+                        parts.push(KI18n.i18nd("plasma_login", "Num Lock is on"));
+                    }
                     if (root.notificationMessage) {
                         parts.push(root.notificationMessage);
                     }
@@ -299,6 +309,9 @@ Item {
                     if (capsLockState.locked) {
                         parts.push(KI18n.i18nd("plasma_login", "Caps Lock is on"));
                     }
+                    if (numLockState.locked && root.loginFailed) {
+                        parts.push(KI18n.i18nd("plasma_login", "Num Lock is on"));
+                    }
                     if (root.notificationMessage) {
                         parts.push(root.notificationMessage);
                     }
@@ -389,6 +402,7 @@ Item {

         function onLoginFailed() {
             notificationMessage = KI18n.i18nd("plasma_login", "Login Failed");
+            loginFailed = true;
             // Only failures time out; started here rather than on every change.
             notificationResetTimer.start();

-- 
2.53.0
